import React from "react";
import { useNavigate } from "react-router-dom";

function StudentDashboard() {

const navigate = useNavigate();
const students = JSON.parse(localStorage.getItem("students")) || [];
const currentUser = localStorage.getItem("currentUser");

/* If no login */
if (!currentUser)
return <h2 style={{ textAlign: "center" }}>Please Login First</h2>;

/* Find student */
const student = students.find(
(s) => s.name && s.name.toLowerCase() === currentUser.toLowerCase()
);

if (!student)
return <h2 style={{ textAlign: "center" }}>No Data Found</h2>;

/* Logout */
const logout = () => {
localStorage.removeItem("isLoggedIn");
localStorage.removeItem("role");
localStorage.removeItem("currentUser");
navigate("/login");
};

return (

<div>

{/* Header */}
<div className="header">

<h1 className="title">Student Dashboard</h1>

<button className="logoutBtn" onClick={logout}>
Logout
</button>

</div>

{/* Student Card Center */}

<div className="studentDashboard">

<div className="studentCard">

<h2>{student.name}</h2>

<p>Math : {student.math}</p>
<p>Science : {student.science}</p>
<p>English : {student.english}</p>
<p>Quiz : {student.quiz}</p>
<p>Assessment : {student.assessment}</p>
<p>Attendance : {student.attendance}%</p>

<h3>Status : {student.status}</h3>

</div>

</div>

</div>

);
}

export default StudentDashboard;